update scm_combined_delivery
set del_flag = '2', del_by = #{delBy}, del_time = sysdate(), update_by = #{delBy}, update_time = sysdate()
where combined_id = #{combinedId}

update scm_combined_delivery_detail
delivery_id = #{deliveryId}, delivery_no = #{deliveryNo}, delivery_detail_id = #{deliveryDetailId}, delivery_quantity = #{deliveryQuantity}, price = #{price}, amount = #{amount}, batch_no = #{batchNo}, production_date = #{productionDate}, expire_date = #{expireDate}, update_by = #{updateBy}, update_time = sysdate()
where detail_id = #{detailId}

update scm_combined_delivery_detail
set del_flag = '2', del_by = #{delBy}, del_time = sysdate(), update_by = #{delBy}, update_time = sysdate()
where detail_id = #{detailId}

mapper.select:
select o.order_id as orderId, o.order_no as orderNo, o.hospital_id as hospitalId, h.hospital_name as hospitalName, o.warehouse_name as warehouse, max(c.delivery_address) as deliveryAddress, coalesce(sum(od.order_quantity), 0) as orderQty, coalesce(( select sum(dd.delivery_quantity) from scm_delivery_detail dd inner join scm_delivery del on del.delivery_id = dd.delivery_id where (dd.del_flag is null or dd.del_flag = '' or dd.del_flag = '0') and (del.del_flag is null or del.del_flag = '' or del.del_flag = '0') and del.combined_id is not null and dd.order_detail_id in (select od2.detail_id from scm_order_detail od2 where od2.order_id = o.order_id) ), 0) as deliveredQty from scm_order o inner join scm_combined_delivery_detail d on d.order_id = o.order_id and (d.del_flag is null or d.del_flag = '' or d.del_flag = '0') inner join scm_combined_delivery c on c.combined_id = d.combined_id and (c.del_flag is null or c.del_flag = '' or c.del_flag = '0') left join scm_order_detail od on od.order_id = o.order_id left join scm_hospital h on o.hospital_id = h.hospital_id
and o.supplier_id = #{supplierId} and o.hospital_id = #{hospitalId}
group by o.order_id, o.order_no, o.hospital_id, h.hospital_name, o.warehouse_name order by o.order_id desc
